use vstd::prelude::*;
verus! {

    /// Given two `Vec<u64>` of length at most 100 each, return a new `Vec<u64>`
    /// that is the concatenation of `a` followed by `b`.
    fn concat(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64>
        requires
            a.len() <= 100,
            b.len() <= 100,
        ensures
            |res: Vec<u64>| {
                // The result has the combined length
                res.len() == a.len() + b.len()
                // For each index in the first part, res[i] == a[i]
                && forall(|i: usize| i < a.len() ==> res[i] == a[i])
                // For each index in the second part, res[i] == b[i - a.len()]
                && forall(|i: usize| a.len() <= i && i < res.len() ==> res[i] == b[i - a.len()])
            }
    {
        let mut res = Vec::new();
        // pre-allocate the needed capacity
        res.reserve(a.len() + b.len());

        // First, append all elements of `a`
        let mut i: usize = 0;
        while i < a.len() {
            invariant
                i <= a.len(),
                res.len() == i,
                forall(|k: usize| k < i ==> res[k] == a[k]);
            decreases(a.len() - i);
            {
                res.push(a[i]);
                i += 1;
            }
        }

        // Then, append all elements of `b`
        let mut j: usize = 0;
        while j < b.len() {
            invariant
                j <= b.len(),
                // we've already pushed `a.len()` elements plus `j` from `b`
                res.len() == a.len() + j,
                // the first `a.len()` elements still match `a`
                forall(|k: usize| k < a.len() ==> res[k] == a[k]),
                // the next `j` elements match the first `j` of `b`
                forall(|k: usize| a.len() <= k && k < a.len() + j
                              ==> res[k] == b[k - a.len()]);
            decreases(b.len() - j);
            {
                res.push(b[j]);
                j += 1;
            }
        }

        res
    }
}